});

// ---- bookmarks: delete ----------------------------------------------------

app.delete('/api/bookmarks/:id', (req, res) => {
  const info = db.prepare('DELETE FROM bookmarks WHERE id = ?').run(req.params.id);
  pruneTags();
  res.json({ deleted: info.changes });
});

// ---- bulk actions ---------------------------------------------------------

app.post('/api/bookmarks/bulk', (req, res) => {
  const { ids, action, value } = req.body || {};
  if (!Array.isArray(ids) || ids.length === 0) {
    return res.status(400).json({ error: 'ids required' });
  }
  const placeholders = ids.map(() => '?').join(',');
  const ts = now();
  const run = db.transaction(() => {
    switch (action) {
      case 'archive':
        db.prepare(
          `UPDATE bookmarks SET archived=1, updated_at=? WHERE id IN (${placeholders})`
        ).run(ts, ...ids);
        break;
      case 'unarchive':
        db.prepare(
          `UPDATE bookmarks SET archived=0, updated_at=? WHERE id IN (${placeholders})`
        ).run(ts, ...ids);
        break;
      case 'read_later':
        db.prepare(
          `UPDATE bookmarks SET read_later=1, updated_at=? WHERE id IN (${placeholders})`
        ).run(ts, ...ids);
        break;
      case 'clear_read_later':
        db.prepare(
          `UPDATE bookmarks SET read_later=0, updated_at=? WHERE id IN (${placeholders})`
        ).run(ts, ...ids);
        break;
      case 'delete':
        db.prepare(`DELETE FROM bookmarks WHERE id IN (${placeholders})`).run(...ids);
        break;
      case 'add_tags':
        for (const id of ids) {
          for (const t of value || []) {
            const tid = ensureTag(t);
            if (tid) linkTag.run(id, tid);
          }
          db.prepare('UPDATE bookmarks SET updated_at=? WHERE id=?').run(ts, id);
        }
        break;
      case 'remove_tag': {
        const tid = getTagId.get(String(value || ''));
        if (tid) {
          db.prepare(
            `DELETE FROM bookmark_tags WHERE tag_id=? AND bookmark_id IN (${placeholders})`
          ).run(tid.id, ...ids);
        }
        break;
      }
      default:
        throw new Error('unknown action');
    }
  });
  try {
    run();
  } catch (e) {
    return res.status(400).json({ error: e.message });
  }
  pruneTags();
  res.json({ ok: true, affected: ids.length });
});

// ---- snapshots ------------------------------------------------------------

const insSnap = db.prepare(
  `INSERT INTO snapshots (bookmark_id, title, image_file, html_file, created_at)
   VALUES (?, ?, ?, ?, ?)`
);

app.get('/api/bookmarks/:id/snapshots', (req, res) => {
  const rows = db
    .prepare('SELECT * FROM snapshots WHERE bookmark_id = ? ORDER BY created_at DESC')
    .all(req.params.id);
  res.json({ snapshots: rows });
});

app.post('/api/bookmarks/:id/snapshots', async (req, res) => {
  const row = getById.get(req.params.id);
  if (!row) return res.status(404).json({ error: 'Not found' });
  try {
    const { capture } = require('./src/snapshot');
    const out = await capture(row.url, row.id);
    const info = insSnap.run(
      row.id,
      out.title || row.title,
      out.image_file,
      out.html_file,
      now()
    );
    res.status(201).json(db.prepare('SELECT * FROM snapshots WHERE id=?').get(info.lastInsertRowid));
  } catch (e) {
    res.status(500).json({ error: 'Snapshot failed: ' + e.message });
  }
});

app.delete('/api/snapshots/:id', (req, res) => {
  const fs = require('fs');
  const snap = db.prepare('SELECT * FROM snapshots WHERE id=?').get(req.params.id);
  if (snap) {
    for (const f of [snap.image_file, snap.html_file]) {
      if (f) try { fs.unlinkSync(path.join(SNAP_DIR, f)); } catch {}
    }
    db.prepare('DELETE FROM snapshots WHERE id=?').run(req.params.id);
  }
  res.json({ ok: true });
});

// ---- saved searches -------------------------------------------------------

app.get('/api/saved-searches', (_req, res) => {
  res.json({
    saved: db.prepare('SELECT * FROM saved_searches ORDER BY name COLLATE NOCASE').all()
  });
});

app.post('/api/saved-searches', (req, res) => {
  const { name, query, view, sort } = req.body || {};
  if (!name || !String(name).trim()) {
    return res.status(400).json({ error: 'name required' });
  }
  const info = db
    .prepare(
      `INSERT INTO saved_searches (name, query, view, sort, created_at)
       VALUES (?, ?, ?, ?, ?)`
    )
    .run(String(name).trim(), query || '', view || 'all', sort || 'created_desc', now());
  res.status(201).json(
    db.prepare('SELECT * FROM saved_searches WHERE id=?').get(info.lastInsertRowid)
  );
});

app.delete('/api/saved-searches/:id', (req, res) => {
  db.prepare('DELETE FROM saved_searches WHERE id=?').run(req.params.id);
  res.json({ ok: true });
});

// ---- preferences ----------------------------------------------------------

app.get('/api/preferences', (_req, res) => {
  const rows = db.prepare('SELECT key, value FROM preferences').all();
  const prefs = { ...DEFAULT_PREFS };
  for (const r of rows) prefs[r.key] = r.value;
  res.json(prefs);
});

app.put('/api/preferences', (req, res) => {
  const body = req.body || {};
  const up = db.prepare(
    'INSERT INTO preferences (key, value) VALUES (?, ?) ON CONFLICT(key) DO UPDATE SET value=excluded.value'
  );
  for (const [k, v] of Object.entries(body)) up.run(k, String(v));
  const rows = db.prepare('SELECT key, value FROM preferences').all();
  const prefs = {};
  for (const r of rows) prefs[r.key] = r.value;
  res.json(prefs);
});

// ---- import / export ------------------------------------------------------

function allRowsWithTags() {
  const rows = db.prepare('SELECT * FROM bookmarks ORDER BY created_at DESC').all();
  return rows.map((r) => ({ ...r, tags: tagsFor(r.id) }));
}

app.get('/api/export', (req, res) => {
  const format = req.query.format === 'html' ? 'html' : 'json';
  const rows = allRowsWithTags();
  if (format === 'html') {
    res.setHeader('Content-Type', 'text/html; charset=utf-8');
    res.setHeader('Content-Disposition', 'attachment; filename="bookmarks.html"');
    return res.send(toNetscapeHTML(rows));
  }
  res.setHeader('Content-Type', 'application/json');
  res.setHeader('Content-Disposition', 'attachment; filename="bookmarks.json"');
  res.send(toJSON(rows));
});

app.post('/api/import', (req, res) => {
  const { data, format } = req.body || {};
  if (!data) return res.status(400).json({ error: 'data required' });
  let items;
  try {
    items = parseImport(data, format);
  } catch (e) {
    return res.status(400).json({ error: 'Could not parse import: ' + e.message });
  }
  let imported = 0, skipped = 0;
  const ts = now();
  const ins = db.prepare(
    `INSERT INTO bookmarks
     (url, title, description, notes, icon, preview_image, domain,
      read_later, archived, created_at, updated_at)
     VALUES (@url,@title,@description,@notes,@icon,@preview_image,@domain,
             @read_later,@archived,@created_at,@updated_at)`
  );
  const tx = db.transaction(() => {
    for (const it of items) {
      if (getByUrl.get(it.url)) { skipped++; continue; }
      const info = ins.run({
        url: it.url,
        title: it.title || '',
        description: it.description || '',
        notes: it.notes || '',
        icon: it.icon || '',
        preview_image: it.preview_image || '',
        domain: it.domain || domainOf(it.url),
        read_later: it.read_later ? 1 : 0,
        archived: it.archived ? 1 : 0,
        created_at: it.created_at || ts,
        updated_at: it.updated_at || ts
      });
      setTags(info.lastInsertRowid, it.tags || []);
      imported++;
    }
  });
  tx();
  res.json({ imported, skipped, total: items.length });
});

// ---- start ----------------------------------------------------------------

const PORT = process.env.PORT || 4000;
app.listen(PORT, '0.0.0.0', () => {
  console.log(`Bookmark manager listening on http://0.0.0.0:${PORT}`);
});

input.content:
:root {
  --bg: #f6f7f9;
  --panel: #ffffff;
  --panel-2: #fbfbfd;
  --text: #1c2024;
  --muted: #6b7280;
  --border: #e5e7eb;
  --accent: #2f6feb;
  --accent-soft: #e8f0fe;
  --danger: #d64545;
  --shadow: 0 1px 3px rgba(16, 24, 40, 0.06), 0 1px 2px rgba(16, 24, 40, 0.04);
  --radius: 10px;
  --fs: 15px;
}
html[data-font="small"] { --fs: 13.5px; }
html[data-font="medium"] { --fs: 15px; }
html[data-font="large"] { --fs: 17px; }

@media (prefers-color-scheme: dark) {
  :root {
    --bg: #14161a;
    --panel: #1c1f25;
    --panel-2: #22262d;
    --text: #e7e9ec;
    --muted: #9aa2ad;
    --border: #2c313a;
    --accent: #5b8def;
    --accent-soft: #24304a;
    --danger: #e06666;
    --shadow: 0 1px 3px rgba(0, 0, 0, 0.3);
  }
}

* { box-sizing: border-box; }
html, body { margin: 0; height: 100%; }
body {
  font-family: -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, Helvetica, Arial, sans-serif;
  font-size: var(--fs);
  color: var(--text);
  background: var(--bg);
  line-height: 1.5;
}

.app { display: grid; grid-template-columns: 260px 1fr; height: 100vh; }

/* ---- sidebar ---- */
.sidebar {
  background: var(--panel);
  border-right: 1px solid var(--border);
  padding: 18px 14px;
  display: flex; flex-direction: column; gap: 16px;
  overflow-y: auto;
}
.brand { display: flex; align-items: center; gap: 8px; font-weight: 700; font-size: 1.05rem; }
.brand-mark { color: var(--accent); }
.add-btn { width: 100%; }

.nav { display: flex; flex-direction: column; gap: 2px; }
.nav-item {
  display: flex; justify-content: space-between; align-items: center;
  background: none; border: none; color: var(--text);
  padding: 8px 10px; border-radius: 8px; cursor: pointer; font-size: 0.95rem;
  text-align: left; width: 100%;
}
.nav-item:hover { background: var(--panel-2); }
.nav-item.active { background: var(--accent-soft); color: var(--accent); font-weight: 600; }
.count { font-size: 0.78rem; color: var(--muted); background: var(--panel-2); padding: 1px 7px; border-radius: 10px; }
.nav-item.active .count { color: var(--accent); background: var(--panel); }

.side-section { display: flex; flex-direction: column; gap: 8px; }
.side-head { display: flex; justify-content: space-between; align-items: center;
  font-size: 0.72rem; text-transform: uppercase; letter-spacing: 0.06em; color: var(--muted); font-weight: 600; }
.link-btn { background: none; border: none; color: var(--accent); cursor: pointer; font-size: 0.8rem; padding: 0; }
.saved-list { display: flex; flex-direction: column; gap: 2px; }
.saved-item { display: flex; align-items: center; justify-content: space-between; gap: 6px;
  padding: 5px 8px; border-radius: 7px; cursor: pointer; font-size: 0.9rem; }
.saved-item:hover { background: var(--panel-2); }
.saved-item .del { color: var(--muted); opacity: 0; }
.saved-item:hover .del { opacity: 1; }

.tag-cloud { display: flex; flex-wrap: wrap; gap: 6px; }
.tag-chip { font-size: 0.8rem; background: var(--panel-2); border: 1px solid var(--border);
  color: var(--text); padding: 2px 9px; border-radius: 20px; cursor: pointer; }
.tag-chip:hover { border-color: var(--accent); color: var(--accent); }
.tag-chip .n { color: var(--muted); margin-left: 4px; font-size: 0.72rem; }

.side-foot { margin-top: auto; display: flex; flex-direction: column; gap: 6px; padding-top: 8px; border-top: 1px solid var(--border); }
.side-foot .link-btn { text-align: left; color: var(--muted); }
.side-foot .link-btn:hover { color: var(--accent); }

/* ---- main ---- */
.main { display: flex; flex-direction: column; overflow: hidden; }
.topbar { display: flex; gap: 12px; padding: 16px 22px; border-bottom: 1px solid var(--border); background: var(--panel); }
.search-wrap { flex: 1; position: relative; display: flex; }
.search { flex: 1; padding: 9px 40px 9px 14px; border: 1px solid var(--border); border-radius: 8px;
  background: var(--panel-2); color: var(--text); font-size: 0.95rem; }
.search:focus { outline: none; border-color: var(--accent); background: var(--panel); }
.help-btn { position: absolute; right: 6px; top: 50%; transform: translateY(-50%);
  width: 24px; height: 24px; border-radius: 50%; border: 1px solid var(--border);
  background: var(--panel); color: var(--muted); cursor: pointer; }
.sort { padding: 0 12px; border: 1px solid var(--border); border-radius: 8px; background: var(--panel-2); color: var(--text); }

.help-box { margin: 12px 22px 0; padding: 12px 16px; background: var(--accent-soft); border-radius: 8px; font-size: 0.85rem; }
.help-box ul { margin: 8px 0 0; padding-left: 18px; }
.help-box code { background: var(--panel); padding: 1px 5px; border-radius: 4px; }

.bulk-bar { display: flex; align-items: center; gap: 8px; flex-wrap: wrap;
  padding: 10px 22px; background: var(--accent-soft); border-bottom: 1px solid var(--border); }
.bulk-bar .spacer { flex: 1; }

.list-head { display: flex; align-items: center; justify-content: space-between; padding: 10px 22px 4px; }
.checkall { font-size: 0.82rem; color: var(--muted); display: flex; align-items: center; gap: 6px; }
.result-count { font-size: 0.82rem; color: var(--muted); }

.list { flex: 1; overflow-y: auto; padding: 6px 22px 40px; }

.card { display: flex; gap: 14px; padding: 14px; background: var(--panel);
  border: 1px solid var(--border); border-radius: var(--radius); margin-bottom: 10px; box-shadow: var(--shadow); }
.card.sel { border-color: var(--accent); box-shadow: 0 0 0 1px var(--accent); }
.card .pick { padding-top: 2px; }
.card .thumb { width: 116px; height: 74px; flex-shrink: 0; border-radius: 8px; object-fit: cover;
  background: var(--panel-2); border: 1px solid var(--border); }
.card .body { flex: 1; min-width: 0; }
.card .row1 { display: flex; align-items: center; gap: 8px; }
.favicon { width: 16px; height: 16px; border-radius: 3px; flex-shrink: 0; }
.card .title { font-weight: 600; font-size: 1rem; color: var(--text); text-decoration: none;
  overflow: hidden; text-overflow: ellipsis; white-space: nowrap; }
.card .title:hover { color: var(--accent); }
.card .domain { font-size: 0.78rem; color: var(--muted); white-space: nowrap; }
.card .desc { color: var(--muted); font-size: 0.9rem; margin: 4px 0 6px;
  display: -webkit-box; -webkit-line-clamp: 2; -webkit-box-orient: vertical; overflow: hidden; }
.card .meta { display: flex; align-items: center; gap: 8px; flex-wrap: wrap; }
.badge { font-size: 0.7rem; padding: 1px 8px; border-radius: 20px; font-weight: 600; }
.badge.later { background: #fff3d6; color: #8a6100; }
.badge.arch { background: #eceff3; color: #5a6472; }
.badge.snap { background: var(--accent-soft); color: var(--accent); }
.card .tags { display: flex; gap: 5px; flex-wrap: wrap; }
.card .tag { font-size: 0.74rem; background: var(--panel-2); border: 1px solid var(--border);
  color: var(--muted); padding: 1px 8px; border-radius: 20px; cursor: pointer; }
.card .tag:hover { color: var(--accent); border-color: var(--accent); }
.card .actions { display: flex; gap: 4px; align-items: flex-start; }
.icon-btn { background: none; border: none; color: var(--muted); cursor: pointer; font-size: 0.95rem;
  padding: 4px 6px; border-radius: 6px; }
.icon-btn:hover { background: var(--panel-2); color: var(--text); }

.empty { text-align: center; color: var(--muted); padding: 60px 20px; }

/* ---- buttons ---- */
.btn { font-size: 0.86rem; padding: 7px 13px; border-radius: 8px; border: 1px solid var(--border);
  background: var(--panel); color: var(--text); cursor: pointer; text-decoration: none; display: inline-block; }
.btn:hover { background: var(--panel-2); }
.btn-primary { background: var(--accent); border-color: var(--accent); color: #fff; }
.btn-primary:hover { filter: brightness(1.05); background: var(--accent); }
.btn-danger { color: var(--danger); border-color: var(--danger); }
.btn-danger:hover { background: var(--danger); color: #fff; }
.btn-ghost { border-color: transparent; background: transparent; color: var(--muted); }

/* ---- modal ---- */
.modal { position: fixed; inset: 0; background: rgba(16, 24, 40, 0.45);
  display: flex; align-items: center; justify-content: center; padding: 20px; z-index: 50; }
.modal-card { background: var(--panel); border-radius: 14px; width: 640px; max-width: 100%;
  max-height: 92vh; display: flex; flex-direction: column; box-shadow: 0 20px 50px rgba(0,0,0,0.3); }
.modal-card.small { width: 440px; }
.modal-card.wide { width: 1000px; }
.modal-head { display: flex; align-items: center; justify-content: space-between;
  padding: 16px 20px; border-bottom: 1px solid var(--border); }
.modal-head h2 { margin: 0; font-size: 1.1rem; }
.modal-body { padding: 18px 20px; overflow-y: auto; display: flex; flex-direction: column; gap: 14px; }
.modal-foot { display: flex; align-items: center; gap: 10px; padding: 14px 20px; border-top: 1px solid var(--border); }
.modal-foot .spacer { flex: 1; }

.field { display: flex; flex-direction: column; gap: 5px; }
.field > span { font-size: 0.82rem; color: var(--muted); font-weight: 600; }
.field input, .field textarea, .field select {
  padding: 8px 11px; border: 1px solid var(--border); border-radius: 8px;
  background: var(--panel-2); color: var(--text); font-size: 0.92rem; font-family: inherit; width: 100%; }
.field input:focus, .field textarea:focus, .field select:focus { outline: none; border-color: var(--accent); }
.field textarea { resize: vertical; }
.url-row { display: flex; gap: 8px; }
.url-row input { flex: 1; }
.field-row { display: flex; gap: 16px; align-items: flex-end; }
.field-row.adv .grow { flex: 1; }
.check { display: flex; align-items: center; gap: 6px; font-size: 0.9rem; }
.preview-row { display: flex; gap: 14px; }
.preview-thumb { width: 150px; height: 96px; object-fit: cover; border-radius: 8px; border: 1px solid var(--border); }
.preview-fields { flex: 1; display: flex; flex-direction: column; gap: 12px; }
.hint { font-size: 0.8rem; color: var(--muted); }
.hint.dup { color: var(--accent); }

.snap-section { border-top: 1px solid var(--border); padding-top: 12px; display: flex; flex-direction: column; gap: 10px; }
.snap-list { display: flex; flex-wrap: wrap; gap: 10px; }
.snap-item { width: 130px; cursor: pointer; }
.snap-item img { width: 130px; height: 84px; object-fit: cover; border-radius: 6px; border: 1px solid var(--border); }
.snap-item .cap { font-size: 0.72rem; color: var(--muted); display: flex; justify-content: space-between; margin-top: 3px; }
.snap-viewer-body { align-items: flex-start; }
.snap-viewer-body img { width: 100%; border-radius: 8px; border: 1px solid var(--border); }

.io-block { display: flex; flex-direction: column; gap: 8px; padding-bottom: 14px; }
.io-block h3 { margin: 0; font-size: 0.95rem; }

.toast { position: fixed; bottom: 22px; left: 50%; transform: translateX(-50%);
  background: var(--text); color: var(--bg); padding: 10px 18px; border-radius: 8px; font-size: 0.88rem; z-index: 100; }

.hidden { display: none !important; }

@media (max-width: 760px) {
  .app { grid-template-columns: 1fr; }
  .sidebar { display: none; }
  .card .thumb { display: none; }
}

